// Routing by STRING FLAG only — no IF node anywhere in this workflow.
// Allowed flags (exact): approve_live | pause_tenant | toggle_service | cost_report
// Unknown flags, missing target tenant, or a failed admin check throw loudly.
const body = $('Webhook').first().json.body ?? {};
const adminRow = $('Validate Admin').first().json ?? {};
const admin_ok = adminRow.role === 'admin' && adminRow.is_active !== false && Boolean(adminRow.id);
const FLAGS = ['approve_live', 'pause_tenant', 'toggle_service', 'cost_report'];
const action = String(body.action ?? '');
if (!FLAGS.includes(action)) throw new Error('admin_rejected: unknown action flag');
if (!admin_ok) throw new Error('admin_rejected: caller is not a registered admin');
if (action !== 'cost_report' && !body.target_tenant_id) throw new Error('admin_rejected: target_tenant_id missing');
if (action === 'toggle_service' && !body.service_code) throw new Error('admin_rejected: service_code missing for toggle_service');
if (action === 'toggle_service' && typeof body.desired_active !== 'boolean') throw new Error('admin_rejected: desired_active must be a boolean for toggle_service');
return [{ json: { admin_owner_id: adminRow.id, admin_ok: true, action, target_tenant_id: body.target_tenant_id ?? null, service_code: body.service_code ?? null, desired_active: body.desired_active ?? null } }];

// Thresholds from the agreed controls: alert at $50 Meta spend, stop tests at $100.
// This node only SETS flags in the output; it never sends an alert by itself.
// Alert delivery channel (owner/admin notification) is TBD — see PLACEHOLDERS.md TBD-D1.
// Sums ALL rows of the Cost Report (not just the first row).
const rows = $('Cost Report (guarded)').all().map(i => i.json);
const total = rows.reduce((s, r) => s + Number(r.total_cost_usd ?? 0), 0);
return [{ json: { total_cost_usd: total, tenants_in_report: rows.length, alert_at_50: total >= 50, stop_tests_at_100: total >= 100 } }];

const r = $('Route by String Flag').first().json;
const a = $('Cost Alert Check').first().json;
return [{ json: { action: r.action, target_tenant_id: r.target_tenant_id, ok: true, alert_at_50: a.alert_at_50 ?? false, stop_tests_at_100: a.stop_tests_at_100 ?? false } }];
